import sys, json, time
for line in sys.stdin:
    msg = json.loads(line)
    if msg.get('method') == 'initialize':
        rsp = {'jsonrpc': '2.0', 'id': msg['id'], 'result': {'protocolVersion': '2024-11-05', 'capabilities': {'tools': {}}, 'serverInfo': {'name': 'example-echo', 'version': '1.0'}}}
    elif msg.get('method') == 'tools/list':
        rsp = {'jsonrpc': '2.0', 'id': msg['id'], 'result': {'tools': [{'name': 'echo', 'description': 'يرد بنفس النص', 'inputSchema': {'type': 'object', 'properties': {'text': {'type': 'string'}}}}]}}
    elif msg.get('method') == 'tools/call':
        rsp = {'jsonrpc': '2.0', 'id': msg['id'], 'result': {'content': [{'type': 'text', 'text': msg['params']['arguments'].get('text', '')}]}}
    else:
        continue
    sys.stdout.write(json.dumps(rsp) + '\n')
    sys.stdout.flush()
